import { FilterRegistry } from 'domain/Filter';
import type { FilterForm } from 'models/Filters';

const hasSpecificValue = (value: FilterForm[string]): boolean =>
  typeof value === 'string' &&
  value.trim().length > 0 &&
  value.trim().toLowerCase() !== 'all';

const getPerformanceToolBrandGrouping = (applied: FilterForm): string => {
  if (hasSpecificValue(applied.portfolios)) {
    return 'Portfolio';
  }

  if (hasSpecificValue(applied.beer_price_segment)) {
    return 'Beer Price Segment';
  }

  return 'All Brands';
};

/**
 * Builds the query string for Commercial Results → Performance Tool navigation.
 * Preserves the filters shared with Performance Tool and selects the grouping
 * responsible for translating Portfolio/Beer Price Segment into page_filter.
 * CR-only dimensions (sku, region, channel, etc.) must not leak into PT.
 */
export const buildCommercialResultsToPerformanceToolFilterQuery = (
  applied: FilterForm,
  kpi = 'volume',
): string =>
  FilterRegistry.buildFilterQueryString(
    {
      zone: applied.zone,
      country: applied.country,
      periods: applied.periods,
      brands: applied.brands,
      sub_brands: applied.sub_brands,
      growth_levers: applied.growth_levers,
      beer_price_segment: applied.beer_price_segment,
      portfolios: applied.portfolios,
    },
    {
      kpis: kpi,
      brand_filter_groupings: getPerformanceToolBrandGrouping(applied),
    },
  );
